package dflow

import (
	"context"
	"encoding/json"

	"github.com/k0923/go/lease"
)

// Status describes ONE node, never the workflow.
type Status string

const (
	Pending   Status = "pending"
	Running   Status = "running"
	Succeeded Status = "succeeded"
	Skipped   Status = "skipped"
	Failed    Status = "failed"
	Suspended Status = "suspended"
)

// SuspensionState is generated by the engine. Token identifies one suspension,
// preventing a previous callback from resolving a later suspension of this node.
type SuspensionState struct {
	Token string `json:"token"`
	Suspension
}

type NodeState struct {
	Status Status         `json:"status"`
	Input  map[string]any `json:"input,omitempty"`
	Output any            `json:"output"`
	Ports  []string       `json:"ports"`
	Error  string         `json:"error,omitempty"`
	// Retained during Resume execution/failure so recovery retries Resume.
	Suspension *SuspensionState `json:"suspension,omitempty"`
}

// State is a snapshot of node states and immutable execution inputs.
// It has no workflow lifecycle/status. The caller decides what these nodes mean
// for its business (finished, awaiting approval, partially successful, etc.).
type State struct {
	Version        int64                `json:"version"`
	DefinitionHash string               `json:"definitionHash"`
	Input          map[string]any       `json:"input"`
	Nodes          map[string]NodeState `json:"nodes"`
}

// Infrastructure is scoped by the business to one execution (RunID/TenantID are
// not API parameters). All calls honor ctx, and values must be deep copies.
type Infrastructure interface {
	lease.Infrastructure
	Load(context.Context) (*State, error)
	// Save atomically checks CURRENT lease generation/expiry and expectedVersion,
	// saves the complete snapshot, increments version, and inserts exactly one
	// Request notification for EACH new suspension token. expectedVersion=0 is
	// insert-only. Return ErrConflict / lease.ErrConflict without mutation.
	// A repeated token must not insert a new request or overwrite its response.
	// The argument is never mutated. Snapshot writes NEVER erase responses.
	Save(ctx context.Context, token lease.Token, state *State, expectedVersion int64) error
	// GetResponse returns nil until a response is durably available. A JSON null
	// response is a non-nil *Response containing "null".
	GetResponse(ctx context.Context, nodeID, suspensionToken string) (*Response, error)
	// Resolve stores the first response AND a distinct Wake notification
	// atomically, without acquiring the execution lease. Only the node's current
	// suspension token may be resolved. Duplicate/stale callbacks return false.
	// Unknown nodes/tokens return ErrWaitNotFound. Responses remain readable
	// through Resume retries until the node's next outcome is committed.
	Resolve(ctx context.Context, nodeID, suspensionToken string, value json.RawMessage) (bool, error)
}

type Response struct {
	Value json.RawMessage `json:"value"`
}

type NotificationKind string

const (
	RequestNotification NotificationKind = "request"
	WakeNotification    NotificationKind = "wake"
)

type Notification struct {
	ID     int64            `json:"id"`
	Kind   NotificationKind `json:"kind"`
	NodeID string           `json:"nodeID"`
	Token  string           `json:"token"`
	// Request is captured at registration so later node state cannot alter it.
	Request json.RawMessage `json:"request,omitempty"`
}

// Outbox delivers at least once. Providers deduplicate by business run scope +
// NodeID + Token. Ack Request after provider acceptance; Ack Wake after Resume
// returns nil error, which ONLY means this drive stopped without an error.
// The external application decides workflow status. Retry lease/storage errors.
type Outbox interface {
	Pending(context.Context) ([]Notification, error)
	Ack(context.Context, int64) error
}
